  '每月1000次解析': { ja: '月1,000回の解析', es: '1.000 análisis al mes', de: '1.000 Analysen pro Monat' },
  '每次最多5页': { ja: '1回あたり最大5ページ', es: 'Hasta 5 páginas por solicitud', de: 'Bis zu 5 Seiten pro Anfrage' },
  '付费点数': { ja: '有料クレジット', es: 'Créditos de pago', de: 'Bezahlte Credits' },
  '一次性点数，不自动续费': { ja: '一回購入型、自動更新なし', es: 'Créditos de un solo pago, sin renovación', de: 'Einmalige Credits, keine automatische Verlängerung' },
  '每次最多100页，不能超过剩余点数': { ja: '1回あたり最大100ページ、残高以内', es: 'Hasta 100 páginas por solicitud dentro del saldo', de: 'Bis zu 100 Seiten pro Anfrage innerhalb des Guthabens' },
