  '浏览器在线转换，仅支持文字型PDF': { ja: 'ブラウザ内変換、テキストPDFのみ対応', es: 'Conversión en el navegador, solo PDF de texto', de: 'Browser-Konvertierung, nur Text-PDFs' },
