const localizedFallback: Record<Exclude<Language, 'zh' | 'en'>, { description: string; intro: string; suffix: string }> = {
  ja: { description: 'ブラウザで使えるHerdownの{tool}。入力を整理し、次の作業に使える形式で出力します。', intro: '入力を確認して変換し、結果をコピーまたはダウンロードできます。', suffix: 'ツール' },
  es: { description: '{tool} de Herdown para usar en el navegador. Procesa la entrada y entrega un resultado listo para tu siguiente tarea.', intro: 'Procesa la entrada, revisa el resultado y cópialo o descárgalo.', suffix: 'herramienta' },
  de: { description: '{tool} von Herdown für den Browser. Eingaben verarbeiten und ein Ergebnis für den nächsten Arbeitsschritt ausgeben.', intro: 'Eingabe verarbeiten, Ergebnis prüfen und kopieren oder herunterladen.', suffix: 'Werkzeug' },
};

export const getPageCopy = (path: string, language: Language): PublicPageCopy | undefined => {
  const explicit = publicPageCopy[path]?.[language];
  if (explicit) return explicit;
  if (language === 'zh' || language === 'en') return undefined;
  const tool = routeTitles[path]?.[language];
  if (!tool) return undefined;
  const template = localizedFallback[language];
  return {
    title: `${tool}｜Herdown`,
    description: template.description.replace('{tool}', tool),
    keywords: `${tool},Herdown,${template.suffix}`,
    heading: tool,
    intro: template.intro,
  };
};

export const getToolTitle = (path: string, language: Language): string | undefined => {
  const localized = publicPageCopy[path]?.[language];
  if (localized) return localized.heading;
  return routeTitles[path]?.[language as Exclude<Language, 'zh' | 'en'>];
};

const replacePattern = (value: string, language: Exclude<Language, 'zh' | 'en'>): string | undefined => {
  const fileMatch = value.match(/^(?:Drop or choose|Choose) a (PDF|DOCX|PPTX|XLSX|CSV|TSV|JSON|XML|RTF) file$/i);
  if (fileMatch) {
    const kind = fileMatch[1].toUpperCase();
    return language === 'ja' ? `${kind}ファイルを選択またはドロップ` : language === 'es' ? `Suelta o elige un archivo ${kind}` : `${kind}-Datei ablegen oder auswählen`;
  }
  const browserMatch = value.match(/^Browser conversion, (.+) files$/i);
  if (browserMatch) {
    return language === 'ja' ? `ブラウザ内変換、${browserMatch[1]}ファイル` : language === 'es' ? `Conversión en el navegador, archivos ${browserMatch[1]}` : `Browser-Konvertierung, ${browserMatch[1]}-Dateien`;
  }
  const chooseMatch = value.match(/^Choose a (.+) file$/i);
  if (chooseMatch) return language === 'ja' ? `${chooseMatch[1]}ファイルを選択` : language === 'es' ? `Elegir archivo ${chooseMatch[1]}` : `${chooseMatch[1]}-Datei auswählen`;
  const pageMatch = value.match(/^Page (\d+)$/i);
  if (pageMatch) return language === 'ja' ? `ページ${pageMatch[1]}` : language === 'es' ? `Página ${pageMatch[1]}` : `Seite ${pageMatch[1]}`;
  const slideMatch = value.match(/^Slide (\d+)$/i);
  if (slideMatch) return language === 'ja' ? `スライド${slideMatch[1]}` : language === 'es' ? `Diapositiva ${slideMatch[1]}` : `Folie ${slideMatch[1]}`;
  const openedMatch = value.match(/^(.+) opened locally\.$/i);
  if (openedMatch) return language === 'ja' ? `${openedMatch[1]}をローカルで開きました。` : language === 'es' ? `${openedMatch[1]} se abrió localmente.` : `${openedMatch[1]} wurde lokal geöffnet.`;
  const packedMatch = value.match(/^(\d+) images were packed into a ZIP\.$/i);
  if (packedMatch) return language === 'ja' ? `${packedMatch[1]}枚の画像をZIPにまとめました。` : language === 'es' ? `Se empaquetaron ${packedMatch[1]} imágenes en un ZIP.` : `${packedMatch[1]} Bilder wurden in ein ZIP gepackt.`;
  const cardCountMatch = value.match(/^(\d+) cards$/i);
  if (cardCountMatch) return language === 'ja' ? `${cardCountMatch[1]}枚のカード` : language === 'es' ? `${cardCountMatch[1]} tarjetas` : `${cardCountMatch[1]} Karten`;
  return undefined;
};

export const translateLegacyText = (value: string, language: Language, path = ''): string => {
  if (language === 'zh' || language === 'en' || !value.trim()) return value;
  const exact = common[value.trim()]?.[language];
  if (exact) return value === value.trim() ? exact : value.replace(value.trim(), exact);
  const routeTitle = routeTitles[path]?.[language as Exclude<Language, 'zh' | 'en'>];
  if (routeTitle && (value.trim() === routeTitle || value.trim() === routeSourceTitles[path] || value.trim() === routeEnglishTitles[path] || value.trim() === publicPageCopy[path]?.zh.heading || value.trim() === publicPageCopy[path]?.en.heading)) return value.replace(value.trim(), routeTitle);
  const patterned = replacePattern(value.trim(), language as Exclude<Language, 'zh' | 'en'>);
  if (patterned) return value === value.trim() ? patterned : value.replace(value.trim(), patterned);
  for (const [source, translations] of Object.entries(common)) {
    if (value.trim() === source) return value.replace(value.trim(), translations[language as Exclude<Language, 'zh' | 'en'>]);
  }
  return value;
};

export const installLegacyLocalization = (language: Language, path: string): (() => void) => {
  if (language === 'zh' || language === 'en' || typeof document === 'undefined') return () => undefined;
  const translate = (root: ParentNode) => {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    const nodes: Text[] = [];
    let current: Node | null = walker.nextNode();
    while (current) {
      const parent = current.parentElement;
      if (parent && !['SCRIPT', 'STYLE', 'TEXTAREA', 'PRE', 'CODE', 'OPTION'].includes(parent.tagName)) nodes.push(current as Text);
      current = walker.nextNode();
    }
    for (const node of nodes) {
      const next = translateLegacyText(node.nodeValue || '', language, path);
      if (next !== node.nodeValue) node.nodeValue = next;
    }
    root.querySelectorAll?.<HTMLElement>('[placeholder],[aria-label],[title]').forEach(element => {
      for (const attribute of ['placeholder', 'aria-label', 'title']) {
        const value = element.getAttribute(attribute);
        if (value) element.setAttribute(attribute, translateLegacyText(value, language, path));
      }
    });
  };
  translate(document.body);
  const observer = new MutationObserver(records => {
    for (const record of records) {
      if (record.type === 'characterData' && record.target.parentElement) translate(record.target.parentElement);
      for (const node of Array.from(record.addedNodes)) if (node.nodeType === Node.ELEMENT_NODE) translate(node as Element);
    }
  });
  observer.observe(document.body, { childList: true, subtree: true, characterData: true });
  return () => observer.disconnect();
};
